// Alle filtre er valgfrie. AI-agenten kan kalde værktøjet med få eller mange filtre.
const input = $json;
function readList(value, label) {
  if (value == null || value === '') return [];
  if (!Array.isArray(value) || !value.every(item => typeof item === 'string' && item.trim())) {
    throw new Error(`${label} must be an array of nonempty strings`);
  }
  return [...new Set(value.map(item => item.trim()))];
}

const restrictToCandidates = input.restrictToCandidates === true || input.restrictToCandidates === 'true';
const candidateIds = readList(input.candidateIds, 'candidateIds');
const aliases = { chickpeas: 'chickpea', 'garbanzo beans': 'chickpea', mushrooms: 'mushroom' };
const requiredIngredients = [...new Set(readList(input.requiredIngredients, 'requiredIngredients').map(item => {
  const name = item.toLowerCase();
  return Object.hasOwn(aliases, name) ? aliases[name] : name;
}))];
const dietaryTags = [...new Set(readList(input.dietaryTags, 'dietaryTags').map(item => item.toLowerCase()))];
const maxMinutes = input.maxMinutes == null || input.maxMinutes === '' ? 0 : Number(input.maxMinutes);
if (!Number.isInteger(maxMinutes) || maxMinutes < 0) {
  throw new Error('maxMinutes must be a nonnegative integer (0 means no limit)');
}
if (restrictToCandidates && candidateIds.length === 0) {
  throw new Error('candidateIds cannot be empty when restrictToCandidates is true');
}

// Understøtter både :graph (din oprindelige query) og det almindelige :Recipe.
const statement = `MATCH (r)
WHERE (r:graph OR r:Recipe)
  AND (NOT $restrictToCandidates OR r.id IN $candidateIds)
  AND ($maxMinutes = 0 OR toInteger(r.minutes) <= $maxMinutes)
  AND all(name IN $requiredIngredients WHERE EXISTS {
    MATCH (r)-[:USES]->(i:Ingredient)
    WHERE toLower(i.name) = name
  })
  AND all(name IN $dietaryTags WHERE EXISTS {
    MATCH (r)-[:HAS_TAG]->(d:DietaryTag)
    WHERE toLower(d.name) = name
  })
OPTIONAL MATCH (r)-[:USES]->(ingredient:Ingredient)
WITH r, collect(DISTINCT ingredient.name) AS ingredients
OPTIONAL MATCH (r)-[:HAS_TAG]->(tag:DietaryTag)
RETURN r.id AS id, r.title AS title, r.description AS description,
       r.instructions AS instructions, toInteger(r.minutes) AS minutes,
       r.source AS source, ingredients, collect(DISTINCT tag.name) AS dietaryTags
ORDER BY minutes, id
LIMIT 10`;
return { json: {
  statement,
  parameters: { restrictToCandidates, candidateIds, requiredIngredients, dietaryTags, maxMinutes }
} };

if ($json.errors?.length) throw new Error(JSON.stringify($json.errors));
const { fields, values } = $json.data ?? {};
if (!Array.isArray(fields) || !Array.isArray(values)) throw new Error("Unexpected Neo4j response");
return { json: { results: values.map(row =>
  Object.fromEntries(fields.map((field, index) => [field, row[index]]))
) } };
